import os
import psycopg2
from flask import Flask, request, jsonify, g
import hashlib
import time

app = Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'appuser')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(host=DB_HOST, dbname=DB_NAME, user=DB_USER, password=DB_PASS)
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

@app.route('/api/v2/transactions', methods=['GET'])
def search_transactions():
    account_id = request.args.get('account_id', '')
    status = request.args.get('status', 'completed')
    merchant = request.args.get('merchant', '')
    date_range = request.args.get('date_range', '30')
    page = request.args.get('page', '1')

    # Build query with filters
    base_query = "SELECT id, amount, merchant_name, tx_date, status FROM transactions WHERE account_id = '{}'".format(account_id)

    if merchant:
        base_query += " AND merchant_name ILIKE '%{}%'".format(merchant)

    if status:
        base_query += " AND status = '{}'".format(status)

    base_query += " AND tx_date >= NOW() - INTERVAL '{} days'".format(date_range)
    base_query += " ORDER BY tx_date DESC LIMIT 50 OFFSET {}".format((int(page) - 1) * 50)

    try:
        cur = get_db().cursor()
        cur.execute(base_query)
        rows = cur.fetchall()
        results = [{'id': r[0], 'amount': float(r[1]), 'merchant': r[2], 'date': str(r[3]), 'status': r[4]} for r in rows]
        return jsonify({'transactions': results, 'query_time_ms': int(time.time() * 1000) % 1000})
    except Exception as e:
        return jsonify({'error': str(e), 'query': base_query}), 500

@app.route('/api/v2/transactions/export', methods=['POST'])
def export_transactions():
    data = request.get_json()
    account_id = data.get('account_id', '')
    format_type = data.get('format', 'csv')
    filters = data.get('filters', {})

    query = "SELECT * FROM transactions WHERE account_id = '{}'".format(account_id)

    if 'merchant' in filters:
        query += " AND merchant_name = '{}'".format(filters['merchant'])

    if 'min_amount' in filters:
        query += " AND amount >= {}".format(filters['min_amount'])

    try:
        cur = get_db().cursor()
        cur.execute(query)
        rows = cur.fetchall()
        # In production this would stream to S3
        return jsonify({'exported_count': len(rows), 'format': format_type})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v2/analytics/spending', methods=['GET'])
def spending_analytics():
    account_id = request.args.get('account_id', '')
    group_by = request.args.get('group_by', 'merchant_name')

    # Whitelist group_by to prevent injection there
    allowed_groups = ['merchant_name', 'status', 'tx_date']
    if group_by not in allowed_groups:
        group_by = 'merchant_name'

    query = "SELECT {}, SUM(amount) as total FROM transactions WHERE account_id = '{}' GROUP BY {} ORDER BY total DESC LIMIT 20".format(
        group_by, account_id, group_by
    )

    try:
        cur = get_db().cursor()
        cur.execute(query)
        rows = cur.fetchall()
        return jsonify({'analytics': [{'category': r[0], 'total': float(r[1])} for r in rows]})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
